int copy_huge_page_entry(struct mm_struct *dst_mm, pte_t *dst_pte,
                         struct vm_area_struct *dst_vma, unsigned long dst_addr,
                         unsigned long src_addr, struct page **pagep) {
    struct page *page;
    int ret = 0;

    if (!*pagep) {
        page = alloc_huge_page();
        if (!page)
            return -ENOMEM;
    } else {
        page = *pagep;
    }

    if (copy_from_user(page_address(page), (void __user *)src_addr, HPAGE_PMD_SIZE)) {
        ret = -EFAULT;
        goto out;
    }

    SetPageUptodate(page);
    if (dst_vma->vm_flags & VM_SHARED)
        set_page_dirty(page);
    else
        set_page_private(page, (unsigned long)src_addr);

    spin_lock(&dst_mm->page_table_lock);
    set_pte_at(dst_mm, dst_addr, dst_pte, pte_mkhuge(pte_mksplit(pte_none(pte_mkdirty(pte_mkwrite(pte_mkowner(pte_mkyoung(PTE_PFN(pte_val(*dst_pte)))))))));
    spin_unlock(&dst_mm->page_table_lock);

    if (!*pagep)
        *pagep = page;

    return 0;

out:
    if (!*pagep)
        __free_huge_page(page);
    return ret;
}

int copy_huge_page_entry(struct mm_struct *dst_mm, pte_t *dst_pte,
                         struct vm_area_struct *dst_vma, unsigned long dst_addr,
                         unsigned long src_addr, struct page **pagep) {
    struct page *page = *pagep;
    int ret = -ENOMEM;

    if (!page) {
        page = alloc_pages(GFP_HIGHUSER | __GFP_ZERO, HPAGE_SHIFT - PAGE_SHIFT);
        if (!page)
            goto out;
    }

    if (copy_from_user(page_address(page), (void __user *)src_addr, HPAGE_SIZE)) {
        ret = -EFAULT;
        goto out_free;
    }

    set_page_state(page, PG_uptodate);

    spin_lock(&dst_mm->page_table_lock);
    set_pte(dst_pte, pte_mkhuge(pte_mksrwp(pte_none(*dst_pte)), page));
    spin_unlock(&dst_mm->page_table_lock);

    *pagep = page;
    return 0;

out_free:
    __free_pages(page, HPAGE_SHIFT - PAGE_SHIFT);
out:
    return ret;
}

int copy_huge_page_table_entry(struct mm_struct *dst_mm, pte_t *dst_pte,
                               struct vm_area_struct *dst_vma, unsigned long dst_addr,
                               unsigned long src_addr, struct page **pagep) {
    struct page *page = *pagep;
    int ret = -ENOMEM;

    if (!page) {
        page = alloc_huge_page();
        if (!page)
            return -ENOMEM;
        *pagep = page;
    }

    if (copy_from_user(page_address(page), (void __user *)src_addr, HPAGE_SIZE)) {
        put_page(page);
        return -EFAULT;
    }

    if (dst_vma->vm_flags & VM_SHARED)
        ret = 0;
    else {
        get_page(page);
        ret = 0;
    }

    spin_lock(&dst_mm->page_table_lock);
    set_pte_at(dst_mm, dst_addr, dst_pte, mk_pte(page, dst_vma->vm_page_prot));
    spin_unlock(&dst_mm->page_table_lock);

    return ret;
}

int copy_huge_page_entry(struct mm_struct *dst_mm, pte_t *dst_pte,
                         struct vm_area_struct *dst_vma,
                         unsigned long dst_addr, unsigned long src_addr,
                         struct page **pagep) {
    struct page *page = *pagep;
    int ret = 0;

    if (!page) {
        page = alloc_huge_page();
        if (!page) {
            return -ENOMEM;
        }
        *pagep = page;
    }

    if (!copy_user_highpage(page, src_addr, dst_vma, dst_addr)) {
        ret = -EFAULT;
        goto out;
    }

    set_page_state(page, PAGE_STATE_DIRTY);

    spin_lock(&dst_mm->page_table_lock);
    pte_t pte = pte_mkhuge(pte_mkdirty(pte_mksrwx(pte_clear(pte_none(pte_t))));
    set_pte_at(dst_mm, dst_addr, dst_pte, pte);
    spin_unlock(&dst_mm->page_table_lock);

    if (dst_vma->vm_flags & VM_SHARED) {
        update_shared_mapping(page, dst_vma, dst_addr);
    } else {
        get_page(page);
    }

out:
    return ret;
}

#include <linux/mm.h>
#include <linux/hugepages.h>
#include <linux/highmem.h>
#include <linux/uaccess.h>

int copy_huge_page_table_entry(struct mm_struct *dst_mm, pte_t *dst_pte,
                               struct vm_area_struct *dst_vma,
                               unsigned long dst_addr, unsigned long src_addr,
                               struct page **pagep) {
    struct page *page;
    void *src, *dst;
    int ret = -EFAULT;

    if (!pagep || !*pagep) {
        page = alloc_huge_page();
        if (!page)
            return -ENOMEM;
        *pagep = page;
    } else {
        page = *pagep;
    }

    src = kmap_atomic(pfn_to_page(virt_to_pfn((void *)src_addr)));
    dst = kmap_atomic(page);

    if (copy_from_user(dst, src, HPAGE_PMD_SIZE)) {
        kunmap_atomic(dst);
        kunmap_atomic(src);
        return -EFAULT;
    }

    kunmap_atomic(dst);
    kunmap_atomic(src);

    clear_highpage(page);
    set_page_dirty(page);

    spin_lock(&dst_mm->page_table_lock);
    pte_t pte = pte_mkyoung(pte_mkdirty(pte_mkhuge(pte_mkspecial(pte_wrprotect(__pte(0))))));
    set_pte_at(dst_mm, dst_addr, dst_pte, pte);
    spin_unlock(&dst_mm->page_table_lock);

    return 0;
}
